// Writes the list of the slots of a window, from slots.json, as Go for the manifest reader (in its package, which knows no wire format) and as
// TypeScript for the plugin SDK and, for the slots of the window itself, the plugin host. Run by `make lib_protocol_generate`; the generated files are committed.
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const read = (path) => readFileSync(fileURLToPath(new URL(path, import.meta.url)), 'utf8')
const write = (path, text) => writeFileSync(fileURLToPath(new URL(path, import.meta.url)), text)

const { slots } = JSON.parse(read('../slots.json'))
const HEADER =
  'Code generated by libs/core/protocol/tools/slots.mjs from libs/core/protocol/slots.json. DO NOT EDIT.'

/** The Go identifier of a slot: SlotTitleBar for titleBar, SlotTitleBarCommands for titleBar.commands. */
const getGoName = (name) =>
  'Slot' +
  name
    .split('.')
    .map((part) => part[0].toUpperCase() + part.slice(1))
    .join('')

const go = [
  `// ${HEADER}`,
  '',
  'package manifest',
  '',
  ...slots.flatMap((one) => [
    `// ${getGoName(one.name)} is ${one.about}, drawn by ${one.owner}.`,
    `const ${getGoName(one.name)} = ${JSON.stringify(one.name)}`,
    '',
  ]),
  '// Slots are the slots of a window, in the order slots.json lists them.',
  `var Slots = []string{${slots.map((one) => getGoName(one.name)).join(', ')}}`,
  '',
  '// IsSlot reports whether the name is a slot of a window.',
  'func IsSlot(name string) bool {',
  '\tswitch name {',
  `\tcase ${slots.map((one) => getGoName(one.name)).join(', ')}:`,
  '\t\treturn true',
  '\t}',
  '\treturn false',
  '}',
  '',
  '// IsWindowSlot reports whether the slot is one of the window itself, which draws one view.',
  'func IsWindowSlot(name string) bool {',
  `\treturn ${slots
    .filter((one) => one.isWindow)
    .map((one) => `name == ${getGoName(one.name)}`)
    .join(' || ')}`,
  '}',
  '',
].join('\n')

/** The key of a slot in SLOT: titleBar, titleBarCommands. */
const getTsKey = (name) =>
  name
    .split('.')
    .map((part, at) => (at === 0 ? part : part[0].toUpperCase() + part.slice(1)))
    .join('')

const ts = [
  `// ${HEADER}`,
  '',
  '// SLOT names the slots of a window. A plugin fills them with the entries of `contributes.slots`.',
  'export const SLOT = {',
  ...slots.flatMap((one) => [
    `  // ${one.about[0].toUpperCase() + one.about.slice(1)}, drawn by ${one.owner}.`,
    `  ${getTsKey(one.name)}: '${one.name}',`,
  ]),
  '} as const',
  '',
  '// SlotName is a slot of a window.',
  'export type SlotName = (typeof SLOT)[keyof typeof SLOT]',
  '',
].join('\n')

const host = [
  `// ${HEADER}`,
  '',
  "import { SLOT, type SlotName } from '@numen/plugin-sdk'",
  '',
  '// WINDOW_SLOTS are the slots of the window itself; each draws one view, of the plugin first by id.',
  `export const WINDOW_SLOTS: readonly SlotName[] = [${slots
    .filter((one) => one.isWindow)
    .map((one) => `SLOT.${getTsKey(one.name)}`)
    .join(', ')}]`,
  '',
].join('\n')

write('../../../plugin/catalog/manifest/slots.go', go)
write('../../../plugin/sdk-ts/src/slots/slotNames.ts', ts)
write('../../../plugin/loader/src/slots/windowSlots.ts', host)
